import hmac
import hashlib
import os
import time

from flask import Blueprint, request

from .errors import problem

bp = Blueprint("webhooks", __name__)

MAX_EVENT_AGE_SECONDS = 300


def _verify_psp_request():
    """Return a problem response if the request fails verification, else None."""
    secret = os.environ.get("PSP_WEBHOOK_SECRET")
    if not secret:
        return problem(401, "Invalid webhook", "Signature verification failed")

    signature = request.headers.get("Psp-Signature", "")
    timestamp = request.headers.get("Psp-Timestamp", "")

    expected = hmac.new(
        secret.encode(), request.get_data(), hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return problem(401, "Invalid webhook", "Signature verification failed")

    try:
        age = time.time() - float(timestamp)
    except ValueError:
        return problem(401, "Invalid webhook", "Invalid timestamp")
    if abs(age) > MAX_EVENT_AGE_SECONDS:
        return problem(401, "Invalid webhook", "Timestamp outside tolerance")

    return None


@bp.post("/webhooks/psp")
def psp_webhook():
    failure = _verify_psp_request()
    if failure is not None:
        return failure

    event = request.get_json()
    # TODO: dispatch on event["type"]
    return "", 204

